    source: "Le Monde Afrique",
    url: "https://www.lemonde.fr/en/le-monde-africa/article/2026/11/24/abdul-el-sayed-seen-from-egypt-a-smear-campaign-reflecting-the-regime-s-anxiety_6787699_124.html",
    time: "10 ore fa",
    pub_ts: 1795528806,
    published_at: "2026-11-24T14:00:06+00:00",
    language: "en",
